package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*; import java.math.BigDecimal;
@TableName("purchase_order_item") public class PurchaseOrderItemEntity { @TableId(type=IdType.AUTO) private Long id; private Long orderId; private Long productId; private String productName; private Integer quantity; private BigDecimal unitPrice; private BigDecimal amount; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getOrderId(){return orderId;} public void setOrderId(Long v){orderId=v;} public Long getProductId(){return productId;} public void setProductId(Long v){productId=v;} public String getProductName(){return productName;} public void setProductName(String v){productName=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} }
